def _extract_issues(response):
    if isinstance(response, list):
        return response
    if not isinstance(response, dict):
        return []
    for key in ("data", "issues", "items", "result"):
        if key in response and isinstance(response[key], list):
            return response[key]
    return []


def main():
    trial_id = "github_label_commenter_python__5XrzLAH"
    repo_name = f"issue-test-{trial_id}"

    composio = Composio()
    composio.create_session(user_id="zealt-user01")

    issues_response = composio.tools.execute(
        "GITHUB_ISSUES_LIST_FOR_REPO",
        {
            "owner": "zealt-user01",
            "repo": repo_name,
            "labels": "bug",
        },
    )

    issues = _extract_issues(issues_response)
    print(f"Found {len(issues)} issue(s) with label 'bug'.")

    for issue in issues:
        issue_number = issue.get("number") if isinstance(issue, dict) else None
        if issue_number is None:
            print(f"Skipping issue without number: {issue}")
